css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; }
.loader::after { content: ''; position: absolute; top: 50%; left: 50%; width: 12%; height: 12%; transform: translate(-50%, -50%); border-radius: 50%; background: var(--accent); z-index: 2; }
.loader .wheel { position: relative; width: 88%; height: 88%; border-radius: 50%; border: calc(var(--loader-size) * .02) solid color-mix(in srgb, var(--accent) 55%, transparent); animation: fw-spin calc(var(--loader-speed) * 4) linear infinite; }
.loader .wheel span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size) * .15); height: calc(var(--loader-size) * .15); margin: calc(var(--loader-size) * -.075) 0 0 calc(var(--loader-size) * -.075); border-radius: 22% 22% 42% 42%; background: var(--accent-2); animation: fw-cabin calc(var(--loader-speed) * 4) linear infinite; }
.loader .wheel span:nth-child(1) { transform: rotate(0deg) translateY(calc(var(--loader-size) * -.44)); }
.loader .wheel span:nth-child(2) { transform: rotate(60deg) translateY(calc(var(--loader-size) * -.44)); }
.loader .wheel span:nth-child(3) { transform: rotate(120deg) translateY(calc(var(--loader-size) * -.44)); }
.loader .wheel span:nth-child(4) { transform: rotate(180deg) translateY(calc(var(--loader-size) * -.44)); }
.loader .wheel span:nth-child(5) { transform: rotate(240deg) translateY(calc(var(--loader-size) * -.44)); }
.loader .wheel span:nth-child(6) { transform: rotate(300deg) translateY(calc(var(--loader-size) * -.44)); }
@keyframes fw-spin { to { rotate: 360deg; } }
@keyframes fw-cabin { from { rotate: 0deg; } to { rotate: -360deg; } }
